def valid_date(date):
    if not date:
        return False

    if len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False

    month, day, year = map(int, date.split('-'))

    if month < 1 or month > 12:
        return False

    if day < 1:
        return False

    if month == 2:
        return day <= 29
    elif month in {4, 6, 9, 11}:
        return day <= 30
    else:
        return day <= 31

